-- /helgon data-driven ur saints (undvik hårdkodat). Display-kolumner + backfill av 11 hub-helgon.
-- Applicerad i prod via MCP (repo-spegling). 2026-08-06.
ALTER TABLE public.saints
  ADD COLUMN IF NOT EXISTS life_line text, ADD COLUMN IF NOT EXISTS note text,
  ADD COLUMN IF NOT EXISTS place_label text, ADD COLUMN IF NOT EXISTS map_href text,
  ADD COLUMN IF NOT EXISTS link_label text, ADD COLUMN IF NOT EXISTS sort_year int,
  ADD COLUMN IF NOT EXISTS show_on_hub boolean NOT NULL DEFAULT false;
-- Backfill (data ur prod; kurerade noter + kart-länkar för de 11 hub-helgonen):
UPDATE public.saints SET show_on_hub=true, sort_year=1020, life_line='Missionsbiskop, 1000-tal', note='Knuten till Växjö och kristnandet av Småland/Värend. Enligt legenden döpte han Olof Skötkonung i Husaby — en legenduppgift, inte ett fast belägg.', place_label='Husaby, Västergötland — dopplatsen (kungsgård & källa)', map_href='/explore?center=58.5667,13.2833&zoom=14', link_label='Visa på kartan →' WHERE code='sigfrid';
UPDATE public.saints SET show_on_hub=true, sort_year=1030, life_line='Olav Haraldsson, † Stiklestad 1030', note='Norges kung och sjöfararnas skyddshelgon. En av Nordens starkaste kulter — kyrkor, offerkällor och pilgrimsvägar mot graven i Nidaros. Egen sida med kyrkoruin, Mälaren-seglingen och källkritik.', place_label=NULL, map_href='/sv/sankt-olof', link_label='Läs mer →' WHERE code='olof';
